const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

// Create a simple solid-color PNG
function createPNG(width, height, r, g, b) {
  // Raw image data (RGB, no alpha for simplicity)
  const raw = [];
  for (let y = 0; y < height; y++) {
    raw.push(0); // filter byte
    for (let x = 0; x < width; x++) {
      raw.push(r, g, b);
    }
  }

  const rawBuf = Buffer.from(raw);
  const compressed = zlib.deflateSync(rawBuf);

  // PNG signature
  const signature = Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);

  // IHDR chunk
  const ihdrData = Buffer.alloc(13);
  ihdrData.writeUInt32BE(width, 0);
  ihdrData.writeUInt32BE(height, 4);
  ihdrData[8] = 8;  // bit depth
  ihdrData[9] = 2;  // color type (RGB)
  ihdrData[10] = 0; // compression
  ihdrData[11] = 0; // filter
  ihdrData[12] = 0; // interlace

  const ihdr = createChunk('IHDR', ihdrData);
  const idat = createChunk('IDAT', compressed);
  const iend = createChunk('IEND', Buffer.alloc(0));

  return Buffer.concat([signature, ihdr, idat, iend]);
}

function createChunk(type, data) {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length, 0);

  const typeBuffer = Buffer.from(type);
  const crcData = Buffer.concat([typeBuffer, data]);

  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(crcData), 0);

  return Buffer.concat([length, typeBuffer, data, crc]);
}

// CRC32 implementation
function crc32(data) {
  let crc = 0xffffffff;
  const table = [];
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let j = 0; j < 8; j++) {
      c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    }
    table[i] = c;
  }
  for (let i = 0; i < data.length; i++) {
    crc = table[(crc ^ data[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

// Create icons
fs.writeFileSync('assets/icon.png', createPNG(1024, 1024, 26, 26, 46)); // Dark blue
fs.writeFileSync('assets/adaptive-icon.png', createPNG(1024, 1024, 26, 26, 46)); // Dark blue
fs.writeFileSync('assets/splash-icon.png', createPNG(1284, 2778, 26, 26, 46)); // Dark blue
fs.writeFileSync('assets/favicon.png', createPNG(48, 48, 26, 26, 46)); // Dark blue

console.log('Created app icons (1024x1024)');
console.log('Created adaptive icon (1024x1024)');
console.log('Created splash icon (1284x2778)');
console.log('Created favicon (48x48)');
"

